add_action( 'wp_footer', 'perfectpixel_scroll_progress_bar' );

function perfectpixel_scroll_progress_bar() {
	if ( 'no' !== strtolower( trim( '{{progress_bar_posts_only}}' ) ) && ! is_singular( 'post' ) ) {
		return;
	}
	$color  = sanitize_hex_color( '{{progress_bar_color}}' );
	$height = max( 1, min( 20, (int) '{{progress_bar_height}}' ) );
	?>
	<div class="perfectpixel-progress" aria-hidden="true" style="position:fixed;top:0;left:0;height:<?php echo (int) $height; ?>px;width:100%;z-index:100000;background:<?php echo esc_attr( $color ? $color : '#2271b1' ); ?>;transform:scaleX(0);transform-origin:0 50%;pointer-events:none"></div>
	<script>
	( function () {
		var bar = document.querySelector( '.perfectpixel-progress' );
		if ( ! bar ) {
			return;
		}
		var ticking = false;
		var update = function () {
			var max = document.documentElement.scrollHeight - window.innerHeight;
			bar.style.transform = 'scaleX(' + ( max > 0 ? Math.min( 1, window.scrollY / max ) : 0 ) + ')';
			ticking = false;
		};
		var request = function () {
			if ( ! ticking ) {
				ticking = true;
				window.requestAnimationFrame( update );
			}
		};
		window.addEventListener( 'scroll', request, { passive: true } );
		window.addEventListener( 'resize', request );
		update();
	} )();
	</script>
	<?php
}
